@page "/recipes"
@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>Browse Recipes</PageTitle>

@if (string.IsNullOrEmpty(Category))
{
    <h1>All Categories</h1>
    <ul class="list-group">
        @foreach (var cat in RecipeService.GetCategories())
        {
            <li class="list-group-item">
                <a href="recipes/@cat.ToLower()">@cat</a>
            </li>
        }
    </ul>
}
else
{
    <h1>@Category Recipes</h1>
    <a href="recipes" class="btn btn-outline-secondary mb-3">← All Categories</a>

    var recipes = RecipeService.GetRecipesByCategory(Category);
    @if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? Category { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe")</PageTitle>

@if (recipe == null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="recipes" class="btn btn-primary">Browse Recipes</a>
}
else
{
    <a href="recipes/@recipe.Category.ToLower()" class="btn btn-outline-secondary mb-3">← Back to @recipe.Category</a>

    <h1>@recipe.Title</h1>
    <p><span class="badge bg-secondary">@recipe.Category</span></p>

    <StarRating RecipeId="@recipe.Id" CurrentRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />

    <h2 class="mt-4">Ingredients</h2>
    <ul>
        @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h2>Steps</h2>
    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
    {
        <p>@step</p>
    }
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe has been submitted successfully.
        <a href="recipes">Browse recipes</a> to see it.
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="model.Title" />
            <ValidationMessage For="() => model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Mexican">Mexican</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="American">American</option>
                <option value="Japanese">Japanese</option>
                <option value="French">French</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="model.Ingredients" />
            <ValidationMessage For="() => model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps" />
            <ValidationMessage For="() => model.Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private bool submitted = false;

    private void HandleSubmit()
    {
        RecipeService.SubmitRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        submitted = true;
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= selectedRating ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  role="button"
                  title="@star star(s)">
                @(star <= selectedRating ? "★" : "☆")
            </span>
        }
    </div>
    @if (selectedRating > 0)
    {
        <p class="mt-2 text-success">You rated this @selectedRating out of 5 stars!</p>
    }
    <p class="text-muted mt-1">
        Average: @CurrentRating.ToString("F1") ⭐ (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedRating = 0;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe != null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

