@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <h5>Rate this recipe</h5>
    <div class="star-rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= selectedRating ? "selected" : "")"
                  @onclick="() => Rate(star)"
                  role="button"
                  title="@star star(s)">
                @(star <= selectedRating ? "★" : "☆")
            </span>
        }
    </div>
    @if (selectedRating > 0)
    {
        <p class="mt-2 text-success">You rated this @selectedRating out of 5 stars!</p>
    }
    <p class="text-muted mt-1">
        Average: @CurrentRating.ToString("F1") ⭐ (@RatingCount ratings)
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int selectedRating = 0;

    private void Rate(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);

        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe != null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}
